//! WebGAL 时间公式。
//!
//! 公式来源: `webgal-video-export-plan.md` 第 3.4 节与 WebGAL 默认配置。所有函数返回
//! 微秒, 避免在时间线里混用毫秒/秒。
//!
//! 两个速度参数的含义与 WebGAL 一致:
//! - `text_speed`(文字显示速度, 0..=100): 越大字出得越快;
//! - `auto_speed`(自动播放速度, 0..=100): 越大, 一句显示完之后等得越短。

use crate::config::TimingConfig;

/// 文本与演出时序。
#[derive(Debug, Clone)]
pub struct Timing {
    pub text_delay_ms: f64,
    pub text_anim_ms: u32,
    pub auto_delay_ms: f64,
    pub voice_tail_ms: u32,
    pub choice_show_ms: u32,
    pub intro_hold_ms: u32,
    pub end_tail_ms: u32,
}

impl Timing {
    /// 从导出配置构造, 数值超出 0..=100 会被夹取.
    pub fn new(config: &TimingConfig) -> Self {
        let text_speed = f64::from(config.text_speed.min(100));
        let auto_speed = f64::from(config.auto_speed.min(100));
        Self {
            text_delay_ms: 3.0 + (100.0 - text_speed) * 1.5,
            text_anim_ms: 200 + (100 - config.text_speed.min(100)) as u32 * 15,
            auto_delay_ms: 250.0 + (100.0 - auto_speed) * 15.0,
            voice_tail_ms: config.voice_tail_ms,
            choice_show_ms: config.choice_show_ms,
            intro_hold_ms: config.intro_hold_ms,
            end_tail_ms: config.end_tail_ms,
        }
    }

    /// 一句对话的持续时间.
    ///
    /// 文字显示完之后再等 `auto_delay_ms` 才进入下一句 —— 这段等待由自动播放速度决定,
    /// 不再另外叠加一个固定的 hold。
    pub fn say_ms(&self, chars: usize, voice_ms: u64) -> u64 {
        let text_ms = self.text_delay_ms * chars as f64 + f64::from(self.text_anim_ms) / 2.0;
        let voice_ms = voice_ms as f64 + f64::from(self.voice_tail_ms);
        let base = text_ms.max(voice_ms).max(0.0);
        (base.round() as u64) + self.auto_delay_ms.round() as u64
    }

    /// 非 hold 的 intro 持续时间.
    pub fn intro_ms(&self, lines: usize, delay_ms: u32) -> u64 {
        1000 + u64::from(delay_ms) * lines as u64
    }

    /// 毫秒转微秒.
    pub fn ms(value: u32) -> u64 {
        u64::from(value) * 1000
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_say_timing_matches_webgal_formula() {
        // 默认与 WebGAL 对齐: 文字显示速度 24, 自动播放速度 12.
        let timing = Timing::new(&TimingConfig::default());
        assert!((timing.text_delay_ms - 117.0).abs() < f64::EPSILON);
        assert_eq!(timing.text_anim_ms, 1340);
        assert!((timing.auto_delay_ms - 1570.0).abs() < f64::EPSILON);
        // 10 个字: 1170 + 670 = 1840, 再加自动播放等待 1570 = 3410ms
        assert_eq!(timing.say_ms(10, 0), 3410);
    }

    #[test]
    fn voice_extends_say() {
        let timing = Timing::new(&TimingConfig::default());
        // 语音 5000 + 尾部 200 = 5200, 再等 1570
        assert_eq!(timing.say_ms(1, 5_000), 6_770);
    }
}
